// lib/clay-wasm.ts
// clay.wasm embedded as base64 so it works in Vercel serverless functions
// where the filesystem layout doesn't include public/ at /var/task/public/
// Generated from @shelby-protocol/clay-codes/dist/clay.wasm (472050 bytes)

const CLAY_WASM_B64 = "";

export async function ensureClayWasm(): Promise<void> {
  const fs   = await import("fs/promises");
  const path = await import("path");

  // All paths the SDK might look for clay.wasm
  const destPaths = [
    "/var/task/node_modules/@shelby-protocol/clay-codes/dist/clay.wasm",
    path.join(process.cwd(), "node_modules", "@shelby-protocol", "clay-codes", "dist", "clay.wasm"),
  ];

  // Decode wasm from embedded base64
  const wasmBuffer = Buffer.from(CLAY_WASM_B64, "base64");

  for (const dest of destPaths) {
    try {
      await fs.access(dest);
      return; // already exists — done
    } catch { /* write it */ }
    try {
      await fs.mkdir(path.dirname(dest), { recursive: true });
      await fs.writeFile(dest, wasmBuffer);
      console.log("[clay-wasm] Written to:", dest);
      return;
    } catch (e) {
      console.warn("[clay-wasm] Could not write to", dest, e);
    }
  }
}
